                        <div class="property-value">${SafeGetValue(charData, '关系阶段')}</div>
                    </div>
                    <div class="property">
                        <div class="property-name">贞洁之证</div>
                        <div class="property-value">${SafeGetValue(charData, '贞操状态')}</div>
                    </div>
                </div>
            </div>
            <div class="section inner-collapsed">
                <div class="section-header" onclick="toggleSection(this)">
                    <span>玉体安否</span><span class="section-arrow">▼</span>
                </div>
                <div class="section-content">
                    <div class="property">
                        <div class="property-name">元气损益</div>
                        <div class="property-value">${SafeGetValue(charData, '织命诅咒状态')}</div>
                    </div>
                </div>
            </div>
        `;
    }

    function switchCharacter(charName, buttonElement) {
        document.querySelectorAll('.tab-button').forEach(btn => btn.classList.remove('active'));
        buttonElement?.classList.add('active');

        document.querySelectorAll('.character-pane').forEach(pane => {
            pane.classList.remove('active');
            pane.style.display = 'none';
        });

        const idMap = {'墨娘': 'moniang', '云娘': 'yunniang', '苏娘': 'suniang', '绣娘': 'xiuniang'};
        const paneId = `pane-${idMap[charName]}`;
        const activePane = document.getElementById(paneId);

        if (activePane) {
            activePane.innerHTML = generateCharacterHTML(charName);
            activePane.style.display = 'block';
            setTimeout(() => activePane.classList.add('active'), 10);
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const gameData = messages?.[0]?.data?.stat_data;

            const container = document.getElementById('scroll-container');
            if (!gameData || !container) {
                if(container) container.innerHTML = "<p style='padding:20px;color:var(--cinnabar-red);'>状态数据加载失败。</p>";
                return;
            }

            GLOBAL_CHARACTER_DATA = gameData;

            const rotationEl = document.getElementById('current-rotation');
            const userAuraEl = document.getElementById('user-aura');
            if(rotationEl) rotationEl.innerText = SafeGetValue(gameData, '世界.四时安寝规.当前轮值');
            if(userAuraEl) userAuraEl.innerText = SafeGetValue(gameData, 'user.当日元气流转');

            const initialTab = document.querySelector('.tab-button.active') || document.getElementById('tab-moniang');
            if (initialTab) {
                const initialCharName = initialTab.innerText;
                switchCharacter(initialCharName, initialTab);
            }
        } catch (error) {
            const card = document.getElementById('scroll-container');
            if(card) card.innerHTML = `<p style='padding:20px;color:var(--cinnabar-red);'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
